/**
 * Brand marks used on lead social-platform chips (web AllIcons names).
 * Colored tiles keep Vue path data; monochrome marks use currentColor on the chip.
 */

import { type ReactElement, type SVGProps } from 'react'

type IconProps = SVGProps<SVGSVGElement>

/**
 * Filled currentColor brand glyph.
 * @param d - Path data.
 * @param viewBox - SVG viewBox.
 * @returns Icon component.
 */
function brandFillIcon(d: string, viewBox = '0 0 24 24') {
  /**
   * @param props - SVG props.
   * @returns Brand mark.
   */
  function Icon(props: IconProps): ReactElement {
    return (
      <svg aria-hidden viewBox={viewBox} fill="currentColor" stroke="none" {...props}>
        <path d={d} />
      </svg>
    )
  }
  return Icon
}

